var a=Math.PI/180;function g(t,n){let e=(n[1]-t[1])*a*Math.cos((t[0]+n[0])/2*a),r=(n[0]-t[0])*a;return Math.hypot(e,r)*6371e3}function p(t,n){let e={distance:Infinity,index:0};for(let r=1;r<n.length;r++){let o=n[r-1],c=n[r],u=Math.cos(o[0]*a),s=(c[1]-o[1])*u,i=c[0]-o[0],f=(t[1]-o[1])*u,h=t[0]-o[0],d=s*s+i*i,l=d?Math.max(0,Math.min(1,(f*s+h*i)/d)):0,m=g(t,[o[0]+i*l,o[1]+s*l/(u||1)]);m<e.distance&&(e={distance:m,index:r-1+l})}return n.length===1&&(e={distance:g(t,n[0]),index:0}),e}function M(t,n){return t.filter(e=>!e.future&&(e.reverse===null||e.reverse===n))}function L(t,n){return n.length<2?t:t.map(e=>({via:e,at:p([e.lat,e.lon],n).index})).sort((e,r)=>e.at-r.at).map(({via:e})=>e)}export{M as n,g as r,L as t};